#include "bc_key.h"
#include "monocypher.h"

/* Generated by bc_keygen inside the build directory: defines bc_key_block_a and bc_key_block_b,
 * the two shares at BC_KEY_SHARE_A_OFFSET and BC_KEY_SHARE_B_OFFSET. */
#include "bc_key_data.h"

/* Joined on first use; the tool and the launcher are single threaded where they call this. */
static uint8_t g_key[BC_KEY_SIZE];
static bool g_joined = false;

const uint8_t *bc_build_key(void)
{
  if (!g_joined) {
    uint8_t b[BC_KEY_SIZE];
    for (int i = 0; i < BC_KEY_SIZE; i++) {
      b[i] = bc_key_block_b[BC_KEY_SHARE_B_OFFSET + i];
    }
    bc_key_join(bc_key_block_a + BC_KEY_SHARE_A_OFFSET, b, g_key);
    crypto_wipe(b, sizeof(b));
    g_joined = true;
  }
  return g_key;
}

void bc_build_key_forget(void)
{
  crypto_wipe(g_key, sizeof(g_key));
  g_joined = false;
}
